_pkey" PRIMARY KEY ("id") );  -- CreateTable CREATE TABLE "attempts" (     "id" UUID NOT NULL,     "assessmentId" UUID NOT NULL,     "candidateId" UUID NOT NULL,     "invitationId" UUID,     "status" "AttemptStatus" NOT NULL DEFAULT 'NOT_STARTED',     "startedAt" TIMESTAMP(3),     "submittedAt" TIMESTAMP(3),     "evaluatedAt" TIMESTAMP(3),     "totalScore" INTEGER NOT NULL DEFAULT 0,     "maxScore" INTEGER NOT NULL DEFAULT 0,     "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,     "updatedAt" TIMESTAMP(3) NOT NULL,      CONSTRAINT "attempts_pkey" PRIMARY KEY ("id") );  -- CreateTable CREATE TABLE "audit_logs" (     "id" UUID NOT NULL,     "actorId" UUID,     "action" VARCHAR(100) NOT NULL,     "entity" VARCHAR(100) NOT NULL,     "entityId" TEXT,     "metadata" JSONB,     "ipAddress" VARCHAR(100),     "userAgent" TEXT,     "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,      CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id") );  -- CreateTable CREATE TABLE "evaluations" (     "id" UUID NOT NULL,     "submissionId" UUID NOT NULL,     "evaluatorId" UUID NOT NULL,     "score" INTEGER NOT NULL,     "feedback" TEXT,     "evaluatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,      CONSTRAINT "evaluations_pkey" PRIMARY KEY ("id") );  -- CreateTable CREATE TABLE "invitations" (     "id" UUID NOT NULL,     "assessmentId" UUID NOT NULL,     "candidateId" UUID NOT NULL,     "email" VARCHAR(255) NOT NULL,     "token" VARCHAR(255) NOT NULL,     "status" "InvitationStatus" NOT NULL DEFAULT 'PENDING',     "acceptedAt" TIMESTAMP(3),     "usedAt" TIMESTAMP(3),     "expiresAt" TIMESTAMP(3),     "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,     "updatedAt" TIMESTAMP(3) NOT NULL,     "deletedAt" TIMESTAMP(3),      CONSTRAINT "invitations_pkey" PRIMARY KEY ("id") );  -- CreateTable CREATE TABLE "payments" (     "id" UUID NOT NULL,     "assessmentId" UUID NOT NULL,     "createdById" UUID NOT NULL,     "provider" "PaymentProvider" NOT NULL DEFAU